                var speed = CastleDestroyers.Combat.Ballistics.Speed(this.aim.ShownPower, this.config.launchSpeedMin, this.config.launchSpeedMax);
                var speedX = Math.cos(radians) * speed;
                var speedY = Math.sin(radians) * speed;
                var startX = this.cannons.MuzzleCenterX(CastleDestroyers.Flow.Side.Player);
                var startY = this.cannons.MuzzleCenterY(CastleDestroyers.Flow.Side.Player);
                var gravity = this.config.gravity;
