                    var fraction = CastleDestroyers.UI.AimPreview.Fraction(i, count);
                    var t = shownTime * (((i + 1) | 0)) / count;
                    var x = startX + speedX * t;
                    var y = startY + speedY * t - 0.5 * gravity * t * t;
